def check_solution():
    solutions_count = 0

    # b2 must be in {1, 2, 3, 4, 5, 6}
    for b2 in range(1, 7):
        # b1 and b0 must be in {0, 1, ..., 6}
        for b1 in range(7):
            for b0 in range(7):
                # n = (b2 b1 b0)_7 = 49*b2 + 7*b1 + b0
                n = 49 * b2 + 7 * b1 + b0

                # a0: remove b0 -> (b2 b1)_7 = 7*b2 + b1
                a0 = 7 * b2 + b1

                # a1: remove b1 -> (b2 b0)_7 = 7*b2 + b0
                a1 = 7 * b2 + b0

                # a2: remove b2 -> (b1 b0)_7 = 7*b1 + b0
                a2 = 7 * b1 + b0

                sum_a = a0 + a1 + a2

                if n == sum_a:
                    print(f"Solution found: b2={b2}, b1={b1}, b0={b0}. n={n}, Sum(a_i)={sum_a}")
                    solutions_count += 1

    return solutions_count

count = check_solution()
print(f"Total number of solutions: {count}")
